import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
total = 0
for i in range(n):
    for j in range(i + 1, n):
        for k in range(j + 1, n):
            x, y, z = a[i], a[j], a[k]
            if x + y > z and x + z > y and y + z > x:
                total += 1
print(total)

